function parseCsvRecords(text) {
  const records = [], n = text.length
  let i = 0
  function parseField() {
    if (i < n && text[i] === '"') {
      i++ // opening quote
      let f = ''
      while (i < n) {
        if (text[i] === '"' && text[i + 1] === '"') { f += '"'; i += 2 }
        else if (text[i] === '"') { i++; return f }
        else { f += text[i]; i++ }
      }
      return f
    }
    let f = ''
    while (i < n && text[i] !== ',' && text[i] !== '\r' && text[i] !== '\n') { f += text[i]; i++ }
    return f
  }
  while (i < n) {
    const row = []
    row.push(parseField())
    while (i < n && text[i] === ',') { i++; row.push(parseField()) }
    if (text[i] === '\r') i++
    if (text[i] === '\n') i++
    if (row.length > 1 || row[0] !== '') records.push(row)
  }
  return records
}

